head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isPopup = false;
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo, scwin.vListProcsStatCd, scwin.clickBzProcsNo;
// dialog 호출용 함수
// 발행기관목록관련
String.prototype.trim = function() {
    return this.replace(/(^\s*)|(\s*$)/gi, "");
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setDate();
        await scwin.searchCode();
        await scwin.listSync();
        let parentWin = $c.frame.path("../");
        if (parentWin.scwin.vScrenID === "ULDSTF07405.gfm") {
            scwin.isPopup = true;
            scwin.setPopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search1_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search1_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.btn_Search1_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF07400.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewOffice(grd_Grid, "기술평가신청", "", 8, 0);
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (scwin.isPopup) {
            scwin.setParent(row);
            await $c.win.closePopup();
        } else {
            if (row > 0) {
                // 그리드에서 선택시
                scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
                scwin.vListProcsStatCd = dts_List.getCellData(row, "LIST_PROCS_STAT_CD");
                scwin.clickBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
            }
            // 수정요청 리스트 팝업창
            if ("34" === scwin.vListProcsStatCd) {
                // 수정요청 리스트 팝업창
                const adjreqUrl = "/lstinvstg/ULDSTF07407.gfm";
                await $c.frame.CreateDialogFrame("ULDSTF07407.gfm", adjreqUrl, "전문평가관리 수정요청 리스트", 50, 50, 940, 300, "window");
            }
            await scwin.openDetail();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07400.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07400.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07400.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07400.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        let wth = 980;
        let hgt = 880;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        scwin.vBzProcsNo = "";
        const options = {
            id: "ULDSTF07401",
            title: "기술평가신청",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("ULDSTF07401.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.btn_New_onclick" });
    }
};

/**
 * @method
 * @name txb_COM_NM_onkeydown
 * @description txb_COM_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_COM_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.txb_COM_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Remk_onclick
 * @description 「비고」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Remk_onclick = async function() {
    try {
        let wth = 830;
        let hgt = 210;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        const options = {
            id: "ULDSTF07402",
            title: "전문평가관리 비고",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("ULDSTF07402.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.btn_Remk_onclick" });
    }
};

/**
 * @method
 * @name btn_ContactPnt_onclick
 * @description 「전문평가기관 연락처 관리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ContactPnt_onclick = async function() {
    try {
        let wth = 1300;
        let hgt = 830;
        let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
        const options = {
            id: "ULDSTF07403",
            title: "전문평가기관 연락처 관리",
            type: "browserPopup",
            width: wth,
            height: hgt,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("ULDSTF07403.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07400.btn_ContactPnt_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "SKIL_VALU_PROG_STAT_CD",
        cnm: "cmb_SKIL_VALU_PROG_STAT_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    objCod = document.getElementById(arrCid[0].cnm);
    strCbd = "^전체";
    for (j = 1; j <= dts_Cod.getRowCount(); j++) {
        if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[0].cid) {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
        }
    }
    objCod.CBData = strCbd;
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&STRT_DD=" + edt_SDate.getValue(); // 검색시작일
    url += "&END_DD=" + edt_EDate.getValue(); // 검색종료일
    url += "&COM_NM=" + txb_COM_NM.getValue(); // 회사명
    url += "&SKIL_VALU_PROG_STAT_CD=" + cmb_SKIL_VALU_PROG_STAT_CD.getValue();
    url += "&LIST_PROCS_STAT=" + cmb_PROCS_STAT_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/lstinvstg/KsqSkilValu.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDate
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setDate = function() {
    //  기간 from~ to  셋팅
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function() {
    let wth = 980;
    let hgt = 880;
    let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF07401",
        title: "전문평가신청상세",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("ULDSTF07401.gfm", options);
};

/**
 * @method
 * @name setParent
 * @description set Parent 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.setParent = function(row) {
    let parentWin = $c.frame.path("../");
    parentWin.dts_List.setCellData(parentWin.dts_List.getFocusedRowIndex(), "ASSGN_COM_NM", dts_List.getCellData(row, "COM_NM"));
    parentWin.dts_List.setCellData(parentWin.dts_List.getFocusedRowIndex(), "BZ_PROCS_NO", dts_List.getCellData(row, "BZ_PROCS_NO"));
};

/**
 * @method
 * @name setPopup
 * @description 팝업인경우 버튼숨김
 * @returns {void}
 * @hidden N
 */
scwin.setPopup = function() {
    btn_ContactPnt.hide();
    btn_New.hide();
    btn_Excel.hide();
};
